// port_typenames.cpp -- the original game's rows by name (port_typenames.h). Units, techs and
// upgrades have the names a Hyperion map gives them (port_hxm_names.h); orders by hand, and
// weapons, flingy, sprites, images, sounds and portraits by names made from the player's files
// (tools/hxmap/gen_typenames.py), are in port_typenames117.h. Both are generated by
// tools/hxmap/gen_cpp.py, so the engine and the tools read the same names.
#include <string.h>

#include "../../h/typelimits.h"
#include "port_hxm_names.h"
#include "port_typenames117.h"
#include "port_typenames.h"

namespace {

struct NamedTable {
  const char *psz;
  const HxmName *pNames;
  int nNames;
  int nRows;  // names from here on are no rows: the unit groups a map's triggers name
};

#define N(name, names, rows) {name, names, static_cast<int>(sizeof names / sizeof names[0]), rows}
const NamedTable kNamed[] = {
    N("units", kHxmUnits, UNIT_TYPES_117 + 1),  // and 228, none
    N("weapons", kHxmWeapons, WEAPON_TYPES_117),
    N("flingy", kHxmFlingy, FLINGY_TYPES_117),
    N("sprites", kHxmSprites, SPRITE_TYPES_117),
    N("images", kHxmImages, IMAGE_TYPES_117),
    N("orders", kHxmOrders, ORDER_TYPES_117 + 1),  // and 189, none
    N("techs", kHxmTechs, TECH_TYPES_117),
    N("upgrades", kHxmUpgrades, UPGRADE_TYPES_117),
    N("sounds", kHxmSounds, SOUND_TYPES_117),
    N("portraits", kHxmPortraits, PORTRAIT_TYPES_117),
};
#undef N

}  // namespace

int TypeNameFind(const char *pszTable, const char *pszName) {
  for (const NamedTable &t : kNamed) {
    if (strcmp(t.psz, pszTable) != 0)
      continue;
    for (int i = 0; i < t.nNames; ++i)
      if (t.pNames[i].n < t.nRows && strcmp(t.pNames[i].psz, pszName) == 0)
        return t.pNames[i].n;
    return -1;
  }
  return -1;
}
